}

/**
 * router-rules' section of the Settings dialog, part 1 of the Routing entry (features/settings.md,
 * "Multi-agent"): its rules, an ordered list an operator edits live, in two views of the same draft.
 *
 * - **By agent** (the first): one card per agent, "Trader answers in → Google Chat · 63 chats", its
 *   chats and senders as chips, and the refusals' card; chats added (several pasted at once), taken
 *   away, moved to another agent (`by-agent.tsx`).
 * - **In order**: the rules as they are read, the first that matches deciding, each a card dragged by
 *   its number or moved from its menu (`in-order.tsx`).
 *
 * Where everything else goes is router-basic's part, drawn right under this one (its default agent):
 * this part reads and writes only router-rules' settings. The config's rules are the default: the
 * operator's replace them whole, and "Use default" takes them away. A chat shows its name when the
 * dashboard has seen it (its conversations' parties), else its id; with many, a search narrows both
 * views. The channels offered are the App's (`channel-*` components, `rules.ts`' `channelsOf`), or one
 * typed (`telegram:support`). The agents are the schema's (the code's agents, without a directory),
 * else every agent of `GET /admin/api/agents`. What is wrong shows where it is (`problemsOf`); the list
 * is saved whole, from the heading, which stays at the top of the panel.
 */

import { GitFork, Plus } from "iconoir-react";
import { useRef, useState } from "react";
import { Button } from "@/components/bui/Button";
import SearchField from "@/components/bui/SearchField";
import { ErrorNote } from "@/components/pikit/error-note";
import { Segmented, SettingsHeading, storedOf } from "@/components/pikit/settings";
import { choicesOf, defineSettings, type JsonSchema, useSettings } from "@/lib/settings";
import { useShell } from "@/lib/shell";
import { ByAgent } from "./by-agent";
import { InOrder, type Row } from "./in-order";
import { useChatNames } from "./parts";
import { channelsOf, cleaned, problemsOf, type Rule } from "./rules";

const same = (a: unknown, b: unknown) => JSON.stringify(a) === JSON.stringify(b);

/** More ids than this in the rules, or more rules: a search over them. */
const SEARCH_FROM = 12;

type View = "agents" | "order";

function RoutingSettings() {
  const routing = useSettings("router-rules");
  const { agents, app } = useShell();
  const names = useChatNames();
  const [view, setView] = useState<View>("agents");
  const [query, setQuery] = useState("");
  const [draft, setDraft] = useState<Row[]>();
  /** The rows whose channel is typed, not chosen. */
  const [typed, setTyped] = useState<ReadonlySet<number>>(new Set());
  const [failed, setFailed] = useState<Error>();
  const nextKey = useRef(1_000_000);

  if (routing.error !== undefined && routing.section === undefined) return <ErrorNote error={routing.error} title="The routing rules cannot be read" />;
  const section = routing.section;
  if (section === undefined) return <p className="text-[13px] text-ink-3">Loading</p>;
  const saved = (section.value.rules ?? []) as Rule[];
  const defaults = (section.defaults.rules ?? []) as Rule[];
  const rows = draft ?? saved.map((rule, key) => ({ key, rule }));
  const rules = rows.map((row) => row.rule);
  const changed = draft !== undefined && !same(rules.map(cleaned), saved);
  const agentSchema = ((section.schema.properties?.rules?.items?.anyOf as JsonSchema[] | undefined)?.[0]?.properties?.agent ?? undefined) as JsonSchema | undefined;
  const choices = choicesOf(agentSchema) ?? (agents ?? []).map((agent) => agent.name);
  const problems = problemsOf(rules, agentSchema === undefined && agents === undefined ? undefined : choices);
  const blocked = problems.some((problem) => problem?.level === "error");
  const known = channelsOf(app);
  const channels = [...new Set([...known, ...rules.flatMap((rule) => (rule.channel !== undefined && rule.channel !== "" ? [rule.channel] : []))])];
  // router-basic's part, under this one, draws where everything else goes (the App's composition, not its settings).
  const fallback = app.components.some((component) => component.name === "router-basic");
  const ids = rules.reduce((sum, rule) => sum + (rule.conversations?.length ?? 0) + (rule.actors?.length ?? 0), 0);
  const searchable = ids > SEARCH_FROM || rules.length > SEARCH_FROM;

  /** The draft as `next`: a rule kept as it was keeps its row's key; a changed or new one gets a new key. */
  const setRules = (next: readonly Rule[]) => {
    const byRule = new Map(rows.map((row) => [row.rule, row.key]));
    setDraft(next.map((rule) => ({ key: byRule.get(rule) ?? nextKey.current++, rule })));
  };
  const save = (next: Rule[]) => {
    setFailed(undefined);
    routing
      .save(storedOf({ rules: next }, section.defaults))
      .then(() => {
        setDraft(undefined);
        setTyped(new Set());
      })
      .catch((thrown: unknown) => setFailed(thrown instanceof Error ? thrown : new Error(String(thrown))));
  };
  const add = () => {
    const key = nextKey.current++;
    setDraft([...rows, { key, rule: { ...(known[0] !== undefined && { channel: known[0] }), agent: "" } }]);
  };

  return (
    <div>
      {failed !== undefined && !changed && (
        <div className="mb-4">
          <ErrorNote error={failed} title="Not saved" />
        </div>
      )}
      <p className="mb-5 text-[13px] text-ink-3">
        {view === "agents"
          ? "Who answers where. A chat is one agent's: when two rules list it, the first one wins (In order shows the order)."
          : "Read from the top: the first rule a message matches picks who answers it."}
      </p>
      {/*
       * The heading stays at the top of the scrolling panel while the rules scroll under it, with Save and
       * Revert while there are changes: nothing comes between the last card and router-basic's part below.
       * It sits on the panel's edge past its top padding (`-top-12`, the panel's `pt-12`) and reaches its
       * sides (`-mx-6 sm:-mx-10`), so nothing shows above or beside it.
       */}
      <div className="sticky -top-12 z-10 -mx-6 bg-page px-6 pt-3 pb-2 sm:-mx-10 sm:px-10">
        <SettingsHeading
          aside={
            <>
              {!same(saved, defaults) && draft === undefined && (
                <Button size="sm" variant="quiet" disabled={routing.saving} onClick={() => save(defaults)}>
                  Use default
                </Button>
              )}
              {view === "order" && (
                <Button size="sm" variant="secondary" onClick={add}>
                  <Plus width={14} height={14} strokeWidth={2} />
                  Add rule
                </Button>
              )}
              {changed && (
                <>
                  <Button
                    size="sm"
                    variant="quiet"
                    disabled={routing.saving}
                    onClick={() => {
                      setDraft(undefined);
                      setTyped(new Set());
                      setFailed(undefined);
                    }}
                  >
                    Revert
                  </Button>
                  <Button size="sm" variant="primary" disabled={routing.saving || blocked} title={blocked ? "Fix the rules marked in red first" : undefined} onClick={() => save(rules.map(cleaned))}>
                    Save
                  </Button>
                </>
              )}
            </>
          }
        >
          Rules <span className="text-[13px] font-normal text-ink-3">{same(saved, defaults) && draft === undefined ? "(default)" : "(changed here)"}</span>
        </SettingsHeading>
        <div className="mt-2 flex flex-wrap items-center gap-2">
          <Segmented<View>
            label="Show the rules"
            value={view}
            options={[
              { value: "agents", label: "By agent" },
              { value: "order", label: "In order" },
            ]}
            onChange={setView}
          />
          {searchable && <SearchField value={query} onChange={setQuery} placeholder="Search agents, chats, ids" label="Search the rules" className="min-w-40 flex-1" />}
        </div>
        {changed && <p className="mt-1 text-right text-[12px] text-ink-3">{blocked ? "Not saved yet: fix what is marked in red first." : "Not saved yet. Applies to new conversations once saved."}</p>}
        {changed && failed !== undefined && (
          <div className="mt-2">
            <ErrorNote error={failed} title="Not saved" />
          </div>
        )}
      </div>
      {view === "agents" ? (
        <div className="mt-3">
          <ByAgent rules={rules} onChange={setRules} problems={problems} agents={choices} channels={channels} names={names} query={query} onShowInOrder={() => setView("order")} />
        </div>
      ) : (
        <InOrder rows={rows} onChange={setDraft} problems={problems} agents={choices} channels={channels} known={known} names={names} query={query} typed={typed} setTyped={setTyped} fallback={fallback} />
      )}
    </div>
  );
}

export default defineSettings({
  id: "router-rules",
  title: "Routing",
  icon: GitFork,
  group: "Agents",
  order: 2,
  entry: "routing",
  requires: ["settings"],
  keywords: ["routing", "rules", "channel", "chat", "chats", "space", "sender", "deny", "refuse", "block", "agent", "by agent"],
  component: RoutingSettings,
});

/**
 * The pieces both views of the Routing section use: how a channel reads, the names of the chats the
 * dashboard has seen, an id as a chip, a box that takes several ids at once, and a rule's note.
 */

import { ArrowRight, InfoCircle, Plus, Trash, WarningTriangle, Xmark } from "iconoir-react";
import { type ReactNode, useEffect, useState } from "react";
import { ActionsMenu, type ActionsMenuItem } from "@/components/bui/ActionsMenu";
import { Button } from "@/components/bui/Button";
import { CHANNELS } from "@/components/pikit/party";
import { api, type ApiConversation, type ApiPage } from "@/lib/api";
import { DENIED, idsIn, type Problem } from "./rules";

/** How a channel reads: its platform's name, and an account after it ("Telegram: support"). */
export function channelLabel(channel: string | undefined): string {
  if (channel === undefined || channel === "") return "Any channel";
  const [kind = channel, account] = channel.split(/:(.*)/s);
  const platform = CHANNELS[kind]?.label ?? kind;
  return account === undefined || account === "" ? platform : `${platform}: ${account}`;
}

/** "1 chat", "63 chats". */
export const counted = (n: number, one: string, many: string) => `${n.toLocaleString()} ${n === 1 ? one : many}`;

/** The conversations read for their names: at most this many pages of the most recently active. */
const PAGES = 4;
const PAGE = 500;
/** The ids of a party that are a rule's chat (`InboundMessage.conversationId`): a Google Chat space, a Telegram or web chat. */
const CHAT_IDS = new Set(["Space", "Chat id"]);

/**
 * The names of the chats the dashboard knows (their channel's `conversation.describe`, `ApiParty`):
 * a chat's id (a space, `spaces/AAQA6yBxAgA`; a chat id) to its name ("Zafiro Hoteles"), from the most
 * recently active conversations, read once. A chat no conversation of them names shows as its id;
 * names that cannot be read are no error (the ids show).
 */
export function useChatNames(): ReadonlyMap<string, string> {
  const [names, setNames] = useState<ReadonlyMap<string, string>>(new Map());
  useEffect(() => {
    let live = true;
    (async () => {
      const found = new Map<string, string>();
      let cursor: string | undefined;
      for (let page = 0; page < PAGES; page++) {
        const read = await api<ApiPage<ApiConversation>>(`/conversations?limit=${PAGE}${cursor === undefined ? "" : `&cursor=${encodeURIComponent(cursor)}`}`);
        for (const { party } of read.items) {
          const name = party?.name?.trim();
          if (name === undefined || name === "") continue;
          for (const id of party?.ids ?? []) if (CHAT_IDS.has(id.label) && !found.has(id.value)) found.set(id.value, name);
        }
        cursor = read.next;
        if (cursor === undefined) break;
      }
      if (live) setNames(found);
    })().catch(() => undefined);
    return () => {
      live = false;
    };
  }, []);
  return names;
}

/** A problem's text, the chat it names (`Problem.shadowed`'s one id) said by its name when known. */
export function named(problem: Problem, names: ReadonlyMap<string, string>): string {
  const [one, other] = problem.shadowed ?? [];
  const name = one === undefined || other !== undefined ? undefined : names.get(one.id);
  return name === undefined || one === undefined ? problem.text : problem.text.replace(one.id, `${name} (${one.id})`);
}

/** Whether `query` (its words, any case) is in any of `texts`. */
export function found(query: string, ...texts: (string | undefined)[]): boolean {
  const words = query.toLowerCase().split(/\s+/).filter(Boolean);
  const text = texts.filter(Boolean).join(" ").toLowerCase();
  return words.every((word) => text.includes(word));
}

/**
 * An id of a rule's list as a chip: the chat's name when known (its id in the tooltip), else the id in
 * monospace. `shadowed` marks one an earlier rule takes first (orange); `actions`, its menu (move it);
 * `onRemove`, its ×.
 */
export function IdChip({ id, name, shadowed, actions, onRemove, label }: { id: string; name?: string; shadowed?: string; actions?: readonly ActionsMenuItem[]; onRemove?: () => void; label: string }) {
  const tone = shadowed !== undefined ? "bg-orange-tint text-orange" : "bg-inset text-ink-2 shadow-hairline";
  return (
    <span title={[name === undefined ? id : `${name} · ${id}`, shadowed].filter(Boolean).join("\n")} className={`inline-flex h-6 max-w-full min-w-0 items-center gap-0.5 rounded-[7px] pr-0.5 pl-2 text-[12.5px] ${tone}`}>
      {shadowed !== undefined && <WarningTriangle width={12} height={12} strokeWidth={2} className="mr-1 shrink-0" />}
      <span className={`min-w-0 truncate ${name === undefined ? "font-mono text-[11.5px]" : ""}`}>{name ?? id}</span>
      {actions !== undefined && actions.length > 0 && (
        <ActionsMenu
          label={`${label}: actions`}
          iconSize={12}
          width="w-56"
          actions={actions}
          className="flex size-5 shrink-0 items-center justify-center rounded-[5px] text-ink-3 hover:bg-hover-2 hover:text-ink aria-expanded:bg-hover-2 aria-expanded:text-ink"
        />
      )}
      {onRemove !== undefined && (
        <button type="button" aria-label={`Remove ${label}`} title="Remove" onClick={onRemove} className="flex size-5 shrink-0 items-center justify-center rounded-[5px] text-ink-3 hover:bg-hover-2 hover:text-ink">
          <Xmark width={11} height={11} strokeWidth={2.2} />
        </button>
      )}
    </span>
  );
}

/** The menu of an id: move it to each of `targets` (an agent's name, or refused), and remove it. */
export function idActions(targets: readonly { value: string; label: string }[], move: (target: string) => void, remove: () => void): ActionsMenuItem[] {
  return [
    ...targets.map((target) => ({ key: `to:${target.value}`, label: target.value === DENIED ? "Refuse it instead" : `Move to ${target.label}`, icon: <ArrowRight />, onSelect: () => move(target.value) })),
    { key: "remove", label: "Remove", icon: <Trash />, danger: true, onSelect: remove },
  ];
}

/** At most this many chips of a list show until "Show all". */
const SHOWN = 24;

/** Chips of a list, the first `SHOWN` until "Show all" (all while a search narrows them). */
export function ChipList({ count, all = false, children }: { count: number; all?: boolean; children: (shown: number) => ReactNode }) {
  const [open, setOpen] = useState(false);
  const shown = open || all ? count : Math.min(count, SHOWN);
  return (
    <div className="flex min-w-0 flex-wrap items-center gap-1">
      {children(shown)}
      {shown < count && (
        <button type="button" onClick={() => setOpen(true)} className="h-6 rounded-[7px] px-2 text-[12.5px] text-ink-3 hover:bg-hover-2 hover:text-ink">
          {`+${(count - shown).toLocaleString()} more`}
        </button>
      )}
    </div>
  );
}

/**
 * Takes ids: a button ("Add chats") that opens a box where several are typed or pasted at once (one
 * per line, or separated by spaces or commas), added with Add or Enter; `extra` goes before Add (where
 * they go).
 */
export function AddIds({ what, placeholder, onAdd, extra, notice, open: startOpen = false }: { what: string; placeholder: string; onAdd: (ids: string[]) => void; extra?: ReactNode; notice?: (ids: string[]) => string | undefined; open?: boolean }) {
  const [open, setOpen] = useState(startOpen);
  const [text, setText] = useState("");
  const ids = idsIn(text);
  const add = () => {
    if (ids.length === 0) return;
    onAdd(ids);
    setText("");
    if (!startOpen) setOpen(false);
  };
  if (!open) {
    return (
      <Button size="xs" variant="quiet" onClick={() => setOpen(true)} className="self-start text-ink-3">
        <Plus width={12} height={12} strokeWidth={2} />
        {`Add ${what}`}
      </Button>
    );
  }
  return (
    <div className="flex flex-col gap-2 rounded-control bg-inset p-2 shadow-hairline">
      <textarea
        aria-label={`Add ${what}: ids`}
        value={text}
        rows={Math.min(6, Math.max(2, text.split("\n").length))}
        placeholder={placeholder}
        autoFocus={!startOpen}
        onChange={(event) => setText(event.target.value)}
        onKeyDown={(event) => {
          if (event.key === "Enter" && !event.shiftKey) {
            event.preventDefault();
            add();
          }
          if (event.key === "Escape" && !startOpen) {
            event.stopPropagation();
            setOpen(false);
          }
        }}
        className="control min-h-14 resize-y py-1.5 font-mono text-[12px] leading-[18px]"
      />
      {notice?.(ids) !== undefined && <Note tone="info">{notice(ids)}</Note>}
      <div className="flex flex-wrap items-center gap-2">
        {extra}
        <span className="ml-auto text-[12px] text-ink-3">{ids.length === 0 ? "One per line, or separated by spaces or commas" : `${ids.length.toLocaleString()} to add`}</span>
        {!startOpen && (
          <Button size="xs" variant="quiet" onClick={() => setOpen(false)}>
            Cancel
          </Button>
        )}
        <Button size="xs" variant="secondary" disabled={ids.length === 0} onClick={add}>
          Add
        </Button>
      </div>
    </div>
  );
}

/** A note under a rule: an error (red), a warning (orange), or only information. */
export function Note({ tone, children, className = "" }: { tone: "error" | "warning" | "info"; children: ReactNode; className?: string }) {
  const colors = tone === "error" ? "bg-red-tint text-red" : tone === "warning" ? "bg-orange-tint text-orange" : "text-ink-3";
  const Icon = tone === "info" ? InfoCircle : WarningTriangle;
  return (
    <p className={`flex items-start gap-2 rounded-control text-[12.5px] leading-[18px] ${tone === "info" ? "px-0.5" : "px-2.5 py-1.5"} ${colors} ${className}`}>
      <Icon width={14} height={14} strokeWidth={1.8} className="mt-0.5 shrink-0" />
      <span>{children}</span>
    </p>
  );
}

/**
 * The Routing section's logic, apart from React (pure, no imports, so a test reads it as it is): a rule
 * as router-rules stores it, the channels an App has, what is wrong with a list of rules, and the edits
 * the "By agent" view makes (a chat added to an agent, moved to another, taken away), which keep the
 * order's meaning: first match wins.
 */

/**
 * One rule, as router-rules stores it: what it matches (a channel; chats, `conversations`, and senders,
 * `actors`, any one of a list), then an agent, or a refusal and its reason.
 */
export type Rule = { channel?: string; conversations?: string[]; actors?: string[]; agent?: string; deny?: true; reason?: string };

/** A rule's lists of ids: its chats and its senders. */
export type IdField = "conversations" | "actors";

/** The ids in a pasted or typed text: split at spaces, new lines, commas and semicolons, each once, in order. */
export function idsIn(text: string): string[] {
  return [...new Set(text.split(/[\s,;]+/).filter((id) => id !== ""))];
}

/** The channel each kit channel component's messages carry (`InboundMessage.channel`'s kind). */
const CHANNEL_OF: Record<string, string> = {
  "channel-web": "web",
  "channel-telegram": "telegram",
  "channel-telegram-webhook": "telegram",
  "channel-http": "http",
  "channel-google-chat": "googlechat",
};

/**
 * Where a component's named instances (`<kind>:<name>`) are in the config: the config keys read, and the
 * field that lists the names. Telegram's are `accounts`; Google Chat's `instances` (in its config, and on
 * Cloudflare its Worker half's too, `channel-google-chat-worker`, which `pikit doctor` keeps the same).
 */
const INSTANCES: Record<string, { keys: readonly string[]; field: string }> = {
  "channel-telegram": { keys: ["channel-telegram"], field: "accounts" },
  "channel-telegram-webhook": { keys: ["channel-telegram-webhook"], field: "accounts" },
  "channel-google-chat": { keys: ["channel-google-chat", "channel-google-chat-worker"], field: "instances" },
};

/**
 * The channels of an App's composition (`ApiApp`), in the order installed: each `channel-*` component's
 * kind (`channel-web` → `web`; another one's name without `channel-`), then its named instances
 * (`telegram:support`, `googlechat:ops`), each once.
 */
export function channelsOf(app: { components: readonly { name: string }[]; config: Record<string, unknown> }): string[] {
  const found: string[] = [];
  for (const { name } of app.components) {
    if (!name.startsWith("channel-")) continue;
    const kind = CHANNEL_OF[name] ?? name.slice("channel-".length);
    found.push(kind);
    const { keys = [], field = "" } = INSTANCES[name] ?? {};
    for (const key of keys) {
      const names = (app.config[key] as Record<string, unknown> | undefined)?.[field];
      if (Array.isArray(names)) for (const each of names) if (typeof each === "string" && each !== "") found.push(`${kind}:${each}`);
    }
  }
  return [...new Set(found)];
}

const text = (value: string | undefined) => (value === undefined || value.trim() === "" ? undefined : value.trim());

/** A list as stored: each id trimmed, the empty ones gone, each once. */
const idList = (ids: readonly string[]) => [...new Set(ids.map((id) => id.trim()).filter((id) => id !== ""))];

/**
 * A rule as stored: its texts trimmed, an empty channel gone, each list's ids trimmed and once; an
 * agent, or a refusal and its reason. A list left with no id stays (empty): taking it away would make
 * the rule match every chat, so `problemsOf` says it is an error instead.
 */
export function cleaned(rule: Rule): Rule {
  const channel = text(rule.channel);
  const reason = text(rule.reason);
  return {
    ...(channel !== undefined && { channel }),
    ...(rule.conversations !== undefined && { conversations: idList(rule.conversations) }),
    ...(rule.actors !== undefined && { actors: idList(rule.actors) }),
    ...(rule.deny === true ? { deny: true as const, ...(reason !== undefined && { reason }) } : { agent: rule.agent ?? "" }),
  };
}

/** Whether `channel` (a rule's) takes a message of `of` (another rule's channel): router-rules' `matchesChannel`. */
const channelTakes = (channel: string, of: string) => of === channel || (!channel.includes(":") && of.startsWith(`${channel}:`));

/** Whether a list of `earlier` takes every id `later`'s takes: no list takes any; a list, only its own. */
const within = (earlier: readonly string[] | undefined, later: readonly string[] | undefined) => earlier === undefined || (later !== undefined && later.every((id) => earlier.includes(id)));

/** Whether every message rule `later` matches is matched by `earlier` first (both cleaned). */
export function covers(earlier: Rule, later: Rule): boolean {
  if (earlier.channel !== undefined && (later.channel === undefined || !channelTakes(earlier.channel, later.channel))) return false;
  return within(earlier.conversations, later.conversations) && within(earlier.actors, later.actors);
}

/** An id of a rule's list that an earlier rule always takes first: here it never matches. */
export interface Shadowed {
  field: IdField;
  id: string;
  /** The place of the rule that takes it first. */
  by: number;
}

/** What is wrong with a rule: an `error` keeps the list from being saved; a `warning` does not. */
export interface Problem {
  level: "error" | "warning";
  text: string;
  /** The ids of its lists an earlier rule takes first (some, not all: then the whole rule is never used). */
  shadowed?: Shadowed[];
}

const NOUN: Record<IdField, [string, string]> = { conversations: ["chat", "chats"], actors: ["sender", "senders"] };

/**
 * What is wrong with each rule, by its place (`undefined`: nothing): no agent chosen, a channel with a
 * space, a list with no id (it would match nothing), an agent that is not one of `agents` now (when
 * they are known), a rule an earlier one always takes first (never used), and ids of its lists an
 * earlier rule takes first (a chat listed in two rules: here it never matches).
 */
export function problemsOf(rules: readonly Rule[], agents?: readonly string[]): (Problem | undefined)[] {
  const stored = rules.map(cleaned);
  return stored.map((rule, index): Problem | undefined => {
    if (rule.deny !== true && (rule.agent === undefined || rule.agent === "")) return { level: "error", text: "Choose an agent, or refuse these messages." };
    if (rule.channel !== undefined && /\s/.test(rule.channel)) return { level: "error", text: "A channel has no spaces: web, telegram, telegram:support." };
    for (const field of ["conversations", "actors"] as const) {
      if (rule[field]?.length === 0) return { level: "error", text: `No ${NOUN[field][1]} listed: add one, or take the condition away.` };
    }
    const before = stored.slice(0, index);
    const earlier = before.findIndex((each) => covers(each, rule));
    if (earlier !== -1) return { level: "warning", text: `Never used: rule ${earlier + 1} above takes these messages first. Move this one above it.` };
    const shadowed = shadowedIn(before, rule);
    if (shadowed.length > 0) {
      const [first] = shadowed;
      const text =
        shadowed.length === 1 && first !== undefined
          ? `${first.id}: rule ${first.by + 1} above takes this ${NOUN[first.field][0]} first, so here it never matches.`
          : `${shadowed.length} of these are taken first by rules above (${[...new Set(shadowed.map((each) => each.by + 1))].map((n) => `rule ${n}`).join(", ")}), so here they never match.`;
      return { level: "warning", text, shadowed };
    }
    if (rule.deny !== true && agents !== undefined && rule.agent !== undefined && !agents.includes(rule.agent)) {
      return { level: "warning", text: `No agent is named ${rule.agent} now: these messages are refused until it is changed.` };
    }
    return undefined;
  });
}

/** The ids of `rule`'s lists that one of `before` (cleaned, in order) takes first: the rule with only that id is covered. */
function shadowedIn(before: readonly Rule[], rule: Rule): Shadowed[] {
  const found: Shadowed[] = [];
  for (const field of ["conversations", "actors"] as const) {
    for (const id of rule[field] ?? []) {
      const by = before.findIndex((each) => covers(each, { ...rule, [field]: [id] }));
      if (by !== -1) found.push({ field, id, by });
    }
  }
  return found;
}

/** What a rule decides: an agent's name, or `DENIED` for a refusal. */
export const DENIED = "!deny";
export const outcomeOf = (rule: Rule): string => (rule.deny === true ? DENIED : (rule.agent ?? ""));

/** The rules of one outcome, for the "By agent" view: the agent (or `DENIED`) and its rules' places, in order. */
export interface Group {
  outcome: string;
  rules: number[];
}

/** The rules grouped by what they decide, each agent in the order its first rule comes, the refusals last. */
export function groupsOf(rules: readonly Rule[]): Group[] {
  const groups = new Map<string, number[]>();
  rules.forEach((rule, index) => {
    const outcome = outcomeOf(rule);
    groups.set(outcome, [...(groups.get(outcome) ?? []), index]);
  });
  const all = [...groups].map(([outcome, places]) => ({ outcome, rules: places }));
  return [...all.filter((group) => group.outcome !== DENIED), ...all.filter((group) => group.outcome === DENIED)];
}

/** The other list of a rule. */
const otherOf = (field: IdField): IdField => (field === "conversations" ? "actors" : "conversations");

/** Whether `rule` lists only ids of `field` on `channel` (and has no other condition): a list the "By agent" view adds to and takes from. */
export const isListOf = (rule: Rule, channel: string | undefined, field: IdField): boolean =>
  rule.channel === channel && rule[field] !== undefined && rule[otherOf(field)] === undefined;

/** `rules` without `id` in the list `field` of the rule at `index`; a rule left with no id is taken away (it would match nothing). */
export function withoutId(rules: readonly Rule[], index: number, field: IdField, id: string): Rule[] {
  return rules.flatMap((rule, at) => {
    const list = rule[field];
    if (at !== index || list === undefined) return [rule];
    const left = list.filter((each) => each !== id);
    return left.length === 0 ? [] : [{ ...rule, [field]: left }];
  });
}

/**
 * `rules` with `ids` (chats or senders of `channel`) decided by `outcome` (an agent's name, or
 * `DENIED`), as the "By agent" view adds and moves them:
 *
 * - each id is taken out of the other rules that list only ids of that channel (`isListOf`): a chat is
 *   one agent's, never two (a rule left with none is taken away);
 * - they join the first rule of `outcome` that is such a list;
 * - with none, a new rule `{ channel, [field]: ids }` of `outcome` goes right before the first rule that
 *   would take all its messages first (a catch-all of the channel, a refusal of every other chat), or
 *   last when none would: a new rule is never added where it can never match.
 *
 * `at` is the place of the rule they are in now.
 */
export function placeIds(rules: readonly Rule[], outcome: string, channel: string | undefined, field: IdField, ids: readonly string[]): { rules: Rule[]; at: number } {
  const wanted = idList(ids);
  const decides = (rule: Rule) => outcomeOf(rule) === outcome;
  const target = rules.findIndex((rule) => decides(rule) && isListOf(rule, channel, field));
  const next: (Rule | undefined)[] = rules.map((rule, at) => {
    if (at === target) return { ...rule, [field]: [...new Set([...(rule[field] ?? []), ...wanted])] };
    if (!isListOf(rule, channel, field)) return rule;
    const left = (rule[field] ?? []).filter((id) => !wanted.includes(id));
    return left.length === (rule[field] ?? []).length ? rule : left.length === 0 ? undefined : { ...rule, [field]: left };
  });
  if (target !== -1) {
    const kept = next.filter((rule): rule is Rule => rule !== undefined);
    return { rules: kept, at: target - next.slice(0, target).filter((rule) => rule === undefined).length };
  }
  const kept = next.filter((rule): rule is Rule => rule !== undefined);
  const added: Rule = { ...(channel !== undefined && { channel }), [field]: wanted, ...(outcome === DENIED ? { deny: true as const } : { agent: outcome }) };
  const before = kept.findIndex((rule) => covers(cleaned(rule), added));
  const at = before === -1 ? kept.length : before;
  return { rules: [...kept.slice(0, at), added, ...kept.slice(at)], at };
}

/** `list` with the item at `from` moved to `to`. */
export function moved<T>(list: readonly T[], from: number, to: number): T[] {
  const next = [...list];
  const [item] = next.splice(from, 1);
  if (item !== undefined) next.splice(Math.max(0, Math.min(to, next.length)), 0, item);
  return next;
}
